void setup() {
pinMode(12, OUTPUT); //настройка вывода 12 на выход
}
void loop() {
digitalWrite(12, HIGH); //включить светодиод (на вывод 12 подается 5V) delay(500); //ждем 0,5 секунды (500 миллисекунд = 0,5 секунды) digitalWrite(12, LOW); //потушить светодиод (на вывод 12 подается 0V) delay(500); //ждем 0,5 секунд (500 миллисекунд = 0,5 секунды)
}
